<?php
namespace App\Http\Controllers; use App\Models\{Member,MembershipLevel,MembershipTransaction}; use Illuminate\Http\Request;
class TransactionController extends Controller { public function index(){return view('transactions.index',['transactions'=>MembershipTransaction::with(['member','level','payments'])->latest()->paginate(15)]);} public function create(){return view('transactions.form',['transaction'=>new MembershipTransaction(['type'=>'Application']),'members'=>Member::where('status','Active')->orderBy('last_name')->get(),'levels'=>MembershipLevel::where('is_active',true)->get()]);} public function store(Request $r){$d=$r->validate(['member_id'=>'required|exists:members,id','membership_level_id'=>'required|exists:membership_levels,id','type'=>'required|in:Application,Renewal','latitude'=>'nullable|required_with:longitude|numeric|between:-90,90','longitude'=>'nullable|required_with:latitude|numeric|between:-180,180','notes'=>'nullable']);$level=MembershipLevel::findOrFail($d['membership_level_id']);$d['amount']=$level->fee;$d['reference_number']='TXN-'.\Illuminate\Support\Str::ulid();$d['expires_at']=now()->addMonths($level->validity_months);\Illuminate\Support\Facades\DB::transaction(function () use ($d) { $transaction=MembershipTransaction::create($d); \Illuminate\Support\Facades\Notification::route('mail',$transaction->member->email)->notify(new \App\Notifications\MembershipTransactionSubmitted($transaction->member->name,$transaction->reference_number,$transaction->type)); });return redirect()->route('transactions.index')->with('success','Transaction created and awaiting payment.');} public function show(MembershipTransaction $transaction){$transaction->load(['member','level','payments']);return view('transactions.show',compact('transaction'));} public function edit(MembershipTransaction $transaction){return view('transactions.form',compact('transaction')+['members'=>Member::orderBy('last_name')->get(),'levels'=>MembershipLevel::where('is_active',true)->get()]);} public function update(Request $r,MembershipTransaction $transaction){$d=$r->validate(['member_id'=>'required|exists:members,id','membership_level_id'=>'required|exists:membership_levels,id','type'=>'required|in:Application,Renewal','latitude'=>'nullable|required_with:longitude|numeric|between:-90,90','longitude'=>'nullable|required_with:latitude|numeric|between:-180,180','notes'=>'nullable','status'=>'required|in:Pending,Paid,Approved,Expired,Cancelled']);if($d['status']==='Approved' && $transaction->payments()->sum('amount') < $transaction->amount)return back()->with('error','Only fully paid transactions may be approved.');$transaction->update($d);return redirect()->route('transactions.show',$transaction)->with('success','Transaction updated.');} public function approve(MembershipTransaction $transaction){if($transaction->payments()->sum('amount') < $transaction->amount)return back()->with('error','Only fully paid transactions may be approved.');$transaction->update(['status'=>'Approved','processed_at'=>now()]);$transaction->member->update(['membership_level_id'=>$transaction->membership_level_id,'status'=>'Active','expires_at'=>$transaction->expires_at]);return back()->with('success','Transaction approved and member record updated.');} }
